const SDK=window.__OIKOS_SDK__;const React=SDK.React.default??SDK.React;const{useDashboard,useStyles,MdiIcon}=SDK;const h=React.createElement;export default function Badge(){const s=useStyles(),d=useDashboard(),e='sensor.inverter_solarman_battery_state_of_charge',soc=d.getFloat(e);const low=Number.isFinite(soc)&&soc<40,accent=low?'#ff453a':s.tokens.color.green,txt=Number.isFinite(soc)?`${Math.round(soc)}%`:'—';return h('button',{type:'button',onClick:()=>d.openMoreInfo(e),style:{border:0,borderRadius:999,padding:'7px 11px',background:`color-mix(in srgb, ${accent} 12%, var(--bg-secondary))`,color:s.tokens.color.primary,display:'inline-flex',alignItems:'center',gap:7,cursor:'pointer',whiteSpace:'nowrap'}},h(MdiIcon,{name:'mdi:battery',size:16,color:accent}),h('span',{style:{fontSize:12,fontWeight:800}},`Batteria · ${txt}`));}
